class Solution:
    def sumOfThree(self, num: int) -> List[int]:
        lo, hi = 0, num
        while lo <= hi:
            mid = (lo + hi) // 2
            if 3 * mid == num:
                return [mid - 1, mid, mid + 1]
            if 3 * mid < num:
                lo = mid + 1
            else:
                hi = mid - 1
        return []

