        while (lo <= hi) {
            long long mid = lo + (hi - lo) / 2;
            if (3 * mid == num) return {mid - 1, mid, mid + 1};
            if (3 * mid < num) lo = mid + 1;
            else hi = mid - 1;
        }
        return {};
    }
};

